 "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#fb7185;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">+56 %</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">ataques impulsados por IA</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">sobre todo suplantaciones con deepfakes y malware con IA</div></div>": "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#fb7185;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">+56 %</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">atacs impulsats per IA</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">sobretot suplantacions amb deepfakes i malware amb IA</div></div>",
 "Una cámara": "Una càmera",
 "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#a3e635;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">−1,93 M$</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">menos de coste</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">en organizaciones que usan mucho la IA y la automatización en seguridad</div></div>": "<div style=\"text-align:center\"><div style=\"font-size:54px;font-weight:800;color:#a3e635;line-height:1.05;font-family:'Space Grotesk', 'Merriweather', sans-serif\">−1,93 M$</div><div style=\"font-size:21px;margin-top:.35em;line-height:1.25\">menys de cost</div><div style=\"font-size:16px;color:#a9b8d6;margin-top:.5em;line-height:1.25\">en organitzacions que fan servir molt la IA i l'automatització en seguretat</div></div>",
